int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    int M = 2 * K;
    int *cnt = (int *)calloc(M * M, sizeof(int));
    int *sum = (int *)calloc((M + 1) * (M + 1), sizeof(int));
    if (!cnt || !sum) return 0;

    for (int i = 0; i < N; i++) {
        long long x, y;
        char c[2];
        scanf("%lld %lld %s", &x, &y, c);

        int xi = (int)(x % M);
        int yi = (int)(y % M);
        if (xi < 0) xi += M;
        if (yi < 0) yi += M;

        if (c[0] == 'W') {
            xi = (xi + K) % M;
        }
        cnt[xi * M + yi]++;
    }

    // 2D prefix sum on M x M torus base board
    for (int i = 0; i < M; i++) {
        int rowsum = 0;
        for (int j = 0; j < M; j++) {
            rowsum += cnt[i * M + j];
            sum[(i + 1) * (M + 1) + (j + 1)] = sum[i * (M + 1) + (j + 1)] + rowsum;
        }
    }

    int ans = 0;

    // For each shift (a, b), satisfied points are those in:
    // [a,a+K) x [b,b+K) and [a+K,a+2K) x [b+K,b+2K) on the 2K-periodic board.
    // After converting W by shifting x by K, this counts all satisfied desires.
    for (int a = 0; a < K; a++) {
        for (int b = 0; b < K; b++) {
            int x1 = a, x2 = a + K;
            int y1 = b, y2 = b + K;

            int s1 = sum[x2 * (M + 1) + y2] - sum[x1 * (M + 1) + y2]
                   - sum[x2 * (M + 1) + y1] + sum[x1 * (M + 1) + y1];

            int x3 = a + K, x4 = a + 2 * K;
            int y3 = b + K, y4 = b + 2 * K;

            // Since M = 2K, x4 = y4 = M, so this is within prefix array bounds.
            int s2 = sum[x4 * (M + 1) + y4] - sum[x3 * (M + 1) + y4]
                   - sum[x4 * (M + 1) + y3] + sum[x3 * (M + 1) + y3];

            int cur = s1 + s2;
            if (cur > ans) ans = cur;
            if (N - cur > ans) ans = N - cur; // opposite coloring
        }
    }

    printf("%d\n", ans);

    free(cnt);
    free(sum);
    return 0;
}

