#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<pair<int,int>> black, white;
    for (int i = 0; i < N; i++) {
        int x, y;
        char c;
        cin >> x >> y >> c;
        if (c == 'B') black.emplace_back(x, y);
        else white.emplace_back(x, y);
    }

    // Map each coordinate into 2K x 2K grid
    auto normalize = [&](int x, int y) -> pair<int,int> {
        x %= (2 * K);
        y %= (2 * K);
        if (x < 0) x += 2 * K;
        if (y < 0) y += 2 * K;
        return {x, y};
    };

    // We'll use a 2D difference array on a (2K+1) x (2K+1) grid for counting overlaps
    int M = 2 * K;
    vector<vector<int>> diff(M + 1, vector<int>(M + 1, 0));

    auto add = [&](int x1, int y1, int x2, int y2, int val) {
        if (x1 >= x2 || y1 >= y2) return;
        diff[x1][y1] += val;
        diff[x2][y1] -= val;
        diff[x1][y2] -= val;
        diff[x2][y2] += val;
    };

    // For black desires: possible phase (a,b) where cell (x,y) is black:
    // (x - a) mod 2K in [0, K-1] and (y - b) mod 2K in [0, K-1]
    // That means a in (x - K + 1 .. x) mod 2K, b in (y - K + 1 .. y) mod 2K
    for (auto &p : black) {
        int x, y;
        tie(x, y) = normalize(p.first, p.second);
        // phase a range
        int x1 = (x - K + 1 + M) % M;
        int x2 = (x + 1) % M;
        // phase b range
        int y1 = (y - K + 1 + M) % M;
        int y2 = (y + 1) % M;
        if (x1 <= x2 && y1 <= y2) {
            add(x1, y1, x2, y2, 1);
        } else if (x1 > x2 && y1 <= y2) {
            add(x1, y1, M, y2, 1);
            add(0, y1, x2, y2, 1);
        } else if (x1 <= x2 && y1 > y2) {
            add(x1, y1, x2, M, 1);
            add(x1, 0, x2, y2, 1);
        } else {
            add(x1, y1, M, M, 1);
            add(0, y1, x2, M, 1);
            add(x1, 0, M, y2, 1);
            add(0, 0, x2, y2, 1);
        }
    }

    // For white desires: possible phase (a,b) where cell (x,y) is white
    // That means (x - a) mod 2K in [K, 2K-1] or (y - b) mod 2K in [K, 2K-1]
    // Equivalent to the complement of black region for (a,b)
    // So white = total - black region; easier: add 1 to all, subtract black region
    for (auto &p : white) {
        int x, y;
        tie(x, y) = normalize(p.first, p.second);
        // For white, we can add 1 everywhere then subtract the black region
        add(0, 0, M, M, 1);
        int x1 = (x - K + 1 + M) % M;
        int x2 = (x + 1) % M;
        int y1 = (y - K + 1 + M) % M;
        int y2 = (y + 1) % M;
        if (x1 <= x2 && y1 <= y2) {
            add(x1, y1, x2, y2, -1);
        } else if (x1 > x2 && y1 <= y2) {
            add(x1, y1, M, y2, -1);
            add(0, y1, x2, y2, -1);
        } else if (x1 <= x2 && y1 > y2) {
            add(x1, y1, x2, M, -1);
            add(x1, 0, x2, y2, -1);
        } else {
            add(x1, y1, M, M, -1);
            add(0, y1, x2, M, -1);
            add(x1, 0, M, y2, -1);
            add(0, 0, x2, y2, -1);
        }
    }

    // Now compute prefix sums to get counts for each phase
    int ans = 0;
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < M; j++) {
            if (i > 0) diff[i][j] += diff[i-1][j];
            if (j > 0) diff[i][j] += diff[i][j-1];
            if (i > 0 && j > 0) diff[i][j] -= diff[i-1][j-1];
            ans = max(ans, diff[i][j]);
        }
    }

    cout << ans << "\n";
    return 0;
}

