using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    int M = 2 * K;
    vector<vector<int>> a(M + 1, vector<int>(M + 1, 0));

    for (int i = 0; i < N; ++i) {
        long long x, y;
        char c;
        cin >> x >> y >> c;

        x %= M;
        y %= M;

        // Convert white points by shifting x by K,
        // so all satisfied points correspond to the same pattern.
        if (c == 'W') x = (x + K) % M;

        a[(int)x + 1][(int)y + 1]++;
    }

    // 2D prefix sums on [0, 2K)
    for (int i = 1; i <= M; ++i) {
        for (int j = 1; j <= M; ++j) {
            a[i][j] += a[i - 1][j] + a[i][j - 1] - a[i - 1][j - 1];
        }
    }

    auto sumRect = [&](int x1, int y1, int x2, int y2) -> int {
        // sum over [x1, x2) x [y1, y2), 0-indexed
        return a[x2][y2] - a[x1][y2] - a[x2][y1] + a[x1][y1];
    };

    int ans = 0;

    for (int sx = 0; sx < K; ++sx) {
        for (int sy = 0; sy < K; ++sy) {
            // Black area after normalization:
            // [sx, sx+K) x [sy, sy+K) on torus of size 2K,
            // which splits into two KxK blocks in [0,2K).
            int cnt = 0;
            cnt += sumRect(sx, sy, sx + K, sy + K);
            cnt += sumRect((sx + K) % M, (sy + K) % M,
                           ((sx + K) % M) + K, ((sy + K) % M) + K);
            // The above second rectangle may exceed boundary only if wrapping,
            // but since sx,sy < K, it is actually [sx+K,2K) x [sy+K,2K).
            // So simpler:
            cnt = sumRect(sx, sy, sx + K, sy + K)
                + sumRect(sx + K, sy + K, M, M);

            // Need the other two wrapped quadrants too when choosing torus shift.
            // Proper black cells for shift (sx,sy) are:
            // [sx,sx+K)×[sy,sy+K) and its opposite modulo 2K.
            // Because sx,sy are in [0,K), this corresponds exactly to:
            // [sx,sx+K)×[sy,sy+K) plus
            // ([0,sx)×[0,sy)) + ([0,sx)×[sy+K,2K)) + ([sx+K,2K)×[0,sy)) + ([sx+K,2K)×[sy+K,2K))
            // Easier is to use known 4-rectangle form.
            cnt = 0;
            cnt += sumRect(sx, sy, sx + K, sy + K);
            cnt += sumRect(0, 0, sx, sy);
            cnt += sumRect(0, sy + K, sx, M);
            cnt += sumRect(sx + K, 0, M, sy);
            cnt += sumRect(sx + K, sy + K, M, M);

            ans = max(ans, cnt);
            ans = max(ans, N - cnt);
        }
    }

    cout << ans << '\n';
    return 0;
}

