                int blockY = py / K;
                int patternColor = (blockX + blockY) % 2 ^ offset;
                int desired = c[i];
                if (patternColor == desired) {
                    // This cell is already correct in the base pattern, we can shift it
                    // by moving the pattern origin within [0, M-1]
                    // We'll mark all possible origins (dx, dy) that make this cell correct.
                    // For a given dx, dy, desired color at (x,y) = patternColor at ((x+dx)%M, (y+dy)%M)
                    // We want: patternColor((x+dx)%M, (y+dy)%M) == desired
                    // Equivalent to: (( (x+dx)%M)/K + ((y+dy)%M)/K) % 2 ^ offset == desired
                    // Since we already know patternColor(px,py) == desired for offset,
                    // we can set dx,dy to make (x+dx)%M == px, (y+dy)%M == py
                    // So dx = (px - x[i] % M + M) % M, dy = (py - y[i] % M + M) % M
