        int[][] sum = new int[M + 1][M + 1];
        for (int i = 1; i <= M; i++) {
            for (int j = 1; j <= M; j++) {
                sum[i][j] = cnt[i][j] + sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1];
            }
        }

        int ans = 0;

        for (int sx = 0; sx < K; sx++) {
            for (int sy = 0; sy < K; sy++) {
                // Count points in:
                // [sx, sx+K) x [sy, sy+K)
                // plus [sx+K, sx+2K) x [sy+K, sy+2K)
                int a = rect(sum, sx, sy, sx + K, sy + K);
                int b = rect(sum, sx + K, sy + K, sx + 2 * K, sy + 2 * K);
                int satisfied = a + b;
                ans = Math.max(ans, satisfied);
                ans = Math.max(ans, N - satisfied); // opposite coloring
            }
        }

        System.out.println(ans);
    }

    // rectangle sum on half-open interval [x1, x2) x [y1, y2)
    static int rect(int[][] sum, int x1, int y1, int x2, int y2) {
        return sum[x2][y2] - sum[x1][y2] - sum[x2][y1] + sum[x1][y1];
    }
}
